import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"无谓损失","description":"","frontmatter":{"title":"无谓损失","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/deadweight-loss.md","filePath":"econ/deadweight-loss.md","lastUpdated":1789023840000}'),h={name:"econ/deadweight-loss.md"};function E(m,a,B,A,_,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="无谓损失" tabindex="-1">无谓损失 <a class="header-anchor" href="#无谓损失" aria-label="Permalink to &quot;无谓损失&quot;">​</a></h1><div class="epigraph"><p>被税收挤掉的那些边际交易，其社会价值高于社会成本；损失的剩余不落在买方、卖方或国库任何一方。</p><footer>—— 据 Marshall, Principles of Economics；Harberger, The Measurement of Waste, American Economic Review, 1964 整理</footer></div><p><a href="/econ/tax-incidence">上一课</a>把楔子 \\(t\\) 按弹性分摊到 \\(p_b\\) 与 \\(p_s\\)，并声明超额负担另账。缺口是效率：交易量下降消灭的那块剩余，不是归宿再问一遍「谁承担 \\(t\\)」。本课钉 Marshall 剩余与 Harberger 三角形，不重写弹性公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>税前竞争点上，边际交易的价值等于成本。从量税插入后 \\(q\\) 下降，被挤掉的那些单位，买方评价仍高于卖方成本，但过不了楔子。买方剩余损失加卖方剩余损失，减去国库收到的 \\(t\\cdot q\\)，剩下一块正的无谓损失（DWL）。局部、无收入效应、小税时</p> \\[\\mathrm{DWL}\\approx \\tfrac12 t\\,\\Delta q=\\tfrac12 t^2\\frac{\\varepsilon_D\\varepsilon_S}{\\varepsilon_D+\\varepsilon_S}\\frac{q}{p}. \\]<p>面积随 \\(t^2\\) 走：小税伤害是二阶的，大税不是。归宿分割矩形，不改变三角形——负担落在哪一侧是分配，三角形是效率。</p><h3 id="无谓损失不是税收收入" tabindex="-1">无谓损失不是税收收入 <a class="header-anchor" href="#无谓损失不是税收收入" aria-label="Permalink to &quot;无谓损失不是税收收入&quot;">​</a></h3><p>国库的矩形是转移，可以用来提供<a href="/econ/public-goods">公共品</a>或做总额返还。三角形是消失的互利，返还也找不回来。把「税很重」说成 DWL，若只是转移大、数量几乎不动（无弹性），效率损失其实小——那正是逆弹性直觉的来源，下一课 Ramsey 会用。</p><p><span class="marginnote">图形：需求以下、供给以上、税后数量以右的三角。Harberger 强调可观测：用税后点的弹性与税率估面积，不必先画出整条曲线。这是应用福利的会计，不是新的均衡定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部：Marshall 剩余。严格一点用等价变分或补偿变分；无收入效应或拟线性时三者重合。工具就是上面的三角形（或梯形，若曲线不是直线）。</p><p>一般均衡：一种税改所有相对价格，浪费是各市场超额负担之和，交叉项由替代矩阵决定。Harberger 的测量把「一块一块三角形」加总，作为第一最佳附近的二次型。已有其他扭曲时，这块面积不是福利变化的全部——那是<a href="/econ/theory-of-second-best">次优</a>。</p>',13)),(e(),n(c,null,{default:t(()=>[d(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20INC%5B%22%E5%BD%92%E5%AE%BF%EF%BC%9A%E8%B0%81%E6%89%BF%E6%8B%85%E6%A5%94%E5%AD%90%22%5D%20--%3E%20RECT%5B%22%E7%9F%A9%E5%BD%A2%EF%BC%9A%E8%BD%AC%E7%A7%BB%E7%BB%99%E5%9B%BD%E5%BA%93%22%5D%0A%20%20INC%20--%3E%20TRI%5B%22%E4%B8%89%E8%A7%92%E5%BD%A2%EF%BC%9A%E6%B6%88%E5%A4%B1%E7%9A%84%E4%BA%92%E5%88%A9%22%5D%0A%20%20TRI%20--%3E%20HAR%5B%22Harberger%EF%BC%9A%E7%94%A8%E5%BC%B9%E6%80%A7%E6%B5%8B%E9%87%8F%22%5D%0A%20%20TRI%20--%3E%20SB%5B%22%E5%B7%B2%E6%9C%89%E6%89%AD%E6%9B%B2%EF%BC%9A%E9%9D%A2%E7%A7%AF%E4%B8%8D%E6%98%AF%E5%85%A8%E6%96%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么会有三角形：数量沿错误的相对价格走。每一单位被挤掉的交易，社会少掉的剩余是该单位上「评价减成本」的积分，税不进入这笔积分——税只是把私人计算推离社会计算。弹性越大，\\(\\Delta q\\) 越大，同样的 \\(t\\) 消灭更多交易。这与归宿的「无弹性者承担价格」同时成立：无弹性者多承担矩形，但三角形仍由双方弹性共同决定 \\(\\Delta q\\)。</p><p><a href="/econ/monopoly-lerner">垄断</a>的 DWL 是另一根楔子（加成），会计同形，来源不同。庇古税挤掉的是有害活动，相对无税市场的「三角形」是校正，不是浪费。商品税的三角形才是本课的无谓损失。两种楔子不要画在同一张福利账上。</p><h3 id="测量是二次型-不是道德" tabindex="-1">测量是二次型，不是道德 <a class="header-anchor" href="#测量是二次型-不是道德" aria-label="Permalink to &quot;测量是二次型，不是道德&quot;">​</a></h3><p>Harberger 1964、1971 把应用福利收成可加的小三角形，假设边际上用消费者剩余、一美元一票。人际权重、收入效应、Gorman 加总不成立时，面积会骗人。本课要的是会计身份：转移加浪费加剩余变化为零（局部）。公平判断另要社会福利函数。</p><p><span class="marginnote">资本税的无谓损失可以落在投资、劳动供给或跨期消费上，不落在「公司」这个法定纳税人上——这与上一课 Harberger 归宿模型是同一一般均衡通道，只是本课问面积，上问落点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收入效应大时，Marshall 三角不是等价变分。配额、价格管制的 DWL 同形，但矩形可能变成寻租而不是国库。次优里，单独缩小一个三角形可能放大别处的三角形。</p><p>后课默认：讨论税先分清矩形（归宿、转移）与三角形（DWL）；小税伤害二阶；已有扭曲时不能把三角当福利变化全文。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>归宿分摊矩形；无谓损失是挤掉交易后消失的剩余。</li><li>小税的 DWL 约 \\(\\tfrac12 t\\Delta q\\)，随 \\(t^2\\) 走。</li><li>Harberger 用弹性测量浪费；一般均衡要加交叉市场。</li><li>庇古校正与商品税浪费不是同一块三角。</li><li>出处：Marshall, <em>Principles</em>；Harberger, <em>AER</em>, 1964；<em>JEL</em>, 1971。</li></ul>',11))])}const u=l(h,[["render",E]]);export{b as __pageData,u as default};
